/* d_a_esa_t60.h (WWHD, true 60 build; generated by tools/t60conv, 2026-11-18): d_a_esa.cpp on a general step
 * length (dt = 1/N). Decomp build only.
 *
 * Converted, the actor executes on every step with g_dt = 1/N; at dt = 1 (N = 1, the 30 Hz fallback, an unconverted
 * actor) every helper returns the original per-frame value (dt-1 check bit-exact). The helpers are the shared ones of
 * d/t60conv.h; d_a_esa.cpp keeps thin calls only.
 *
 * Sites (tool classification; review items are left unchanged in the source):
 *     183 daEsa_Execute          tmr    auto    first-step AI-timer (decision timer: first step)
 *     127 bg_check               smth   auto    6 / cloth60_share (integer per-frame add: exact per 30 Hz frame)
 *     170 esa_setRipple          snd    auto    11 (one-shot start in an event function, unchanged)
 *     191 daEsa_Execute          rnd    auto    8 (per-event draw, unchanged)
 *     192 daEsa_Execute          rnd    auto    8 (per-event draw, unchanged)
 *     195 daEsa_Execute          rnd    auto    8 (per-event draw, unchanged)
 *     196 daEsa_Execute          rnd    auto    8 (per-event draw, unchanged)
 *     206 daEsa_Execute          rnd    auto    8 (per-event draw, unchanged)
 *     214 daEsa_Execute          rnd    review  8 / first-step AI-timer: draw in a conditional block that is not a clear state change
 *     215 daEsa_Execute          rnd    review  8 / first-step AI-timer: draw in a conditional block that is not a clear state change
 *     217 daEsa_Execute          rnd    auto    8 (per-event draw, unchanged)
 *     218 daEsa_Execute          rnd    auto    8 (per-event draw, unchanged)
 *     231 daEsa_Execute          rnd    auto    8 (per-event draw, unchanged)
 *     256 daEsa_Execute          tmr    auto    first-step AI-timer (decision on a first-step timer: first step)
 *     260 daEsa_Execute          rnd    auto    first-step AI-timer addendum (decision draw on the first step, once per frame)
 *     271 daEsa_Execute          tmr    review  first-step AI-timer: decision on a first-step timer with per-step motion in its body: hold the decision (t60c::held) and gate the frame-level statements on the first step by hand
 *     272 daEsa_Execute          calc   auto    central
 *
 * Hand review (2026-11-18):
 *   bg_check's `angle.y -= 0x8000` is the wall-hit reflection (an event inside cBgS_LineCross): unchanged, per step
 *     (tool fix: an add inside a collision-hit block is no per-frame add).
 *   daEsa_Execute's landing reaction (`st != 0`: water start, the ground bounce with its draws, the friction, the stop)
 *     runs on the frame's first step from the previous step's ground state (= the frame start's state, as the
 *     original reads its previous frame's bg_check); the later steps of the landing frame keep moving as in the
 *     original's frame.
 *   The free flight: pos.x / pos.z += speed x dt, speed.y -= 3 dt, pos.y by esa60_fall (the exact arc: N steps add
 *     the original's one-frame `pos.y += v; v -= 3` exactly, in real arithmetic).
 *   The water bob mBobAngle += 3000: the step's share (t60c::share, exact per frame).
 *   The bait taken (mTaken 0x23): the splash draw and the delete stay per event (unchanged, tool's first-step AI-timer gate removed:
 *     the delete ends the draws, so it is one draw per event).
 *
 *   The state dispatch (mActionState) takes the frame's first-step state on every step (the 30 Hz visual-motion rule (2)): a state set
 *     on a step (water start 3, the stop 4, the timer's 3 -> 4) first runs its body on the next frame, as in the
 *     original; after the init (state < 1 on the first step) the later steps run state 1.
 *   The ground stop (speedF < 0.1: state 4, return before the move) ends the frame's motion for its later steps too
 *     (esa60_stop / esa60_stopped, a frame mark).
 *
 * Not in kT60Converted: the profile is added after the paired runs. */
#pragma once
#include "d/t60conv.h"

/* the free-flight height step for `pos.y += v; v -= g` per frame: N steps of v x dt + g dt (1 - dt) / 2 add exactly the
 * original's v over the frame (the explicit-Euler arc, not the true parabola); dt = 1: v */
static inline f32 esa60_fall(f32 v, f32 g) {
#ifdef T60C_NEGCTRL
    return v;
#else
    if (!t60c::on())
        return v;
    f32 dt = t60::dt();
    return v * dt + 0.5f * g * dt * (1.0f - dt);
#endif
}

/* the state dispatched on this step: the frame's first-step state; after the init (a first-step state < 1, run once in
 * the original's frame, falling through into state 1) the later steps run state 1 (the init is not repeated; a state
 * the init's frame set from 1 runs next frame) */
static inline u32 esa60_act(const void* k, s32 live) {
    s32 h = t60c::heldInt(live, 1, k);
    return (u32)(h < 1 ? (live < 1 ? live : 1) : h);
}

/* the ground stop on a step of this frame: the later steps skip the move as the original's frame does */
static inline void esa60_stop(const void* k) {
    t60c::mark(2, k);
}
static inline bool esa60_stopped(const void* k) {
    if (t60c::on() && t60::first_step())
        t60c::unmark(2, k);
    return t60c::marked(2, k);
}

/*: the position at the frame's start (current.pos before the first step's move), held
 * over the frame's steps (bg_check's wall check runs the original's per-frame decision on the tick30 step from it).
 * dt 1: the live position (unused there: bg_check reads old.pos). */
static inline void esa60_frameStart(esa_class* a, cXyz* out) {
    union { f32 f; s32 i; } x, y, z;
    x.f = a->current.pos.x;
    y.f = a->current.pos.y;
    z.f = a->current.pos.z;
    x.i = t60c::heldInt(x.i, 20, a);
    y.i = t60c::heldInt(y.i, 21, a);
    z.i = t60c::heldInt(z.i, 22, a);
    out->x = x.f;
    out->y = y.f;
    out->z = z.f;
}
